class NumArray {
    private int[] prefix;
    public NumArray(int[] nums) {
        prefix = new int[nums.length + 1];
        for (int i = 0; i < nums.length; i++) prefix[i + 1] = prefix[i] + nums[i];
    }
    public int sumRange(int left, int right) {
        return prefix[right + 1] - prefix[left];
    }
}

class NumArray {
    private int[] nums;
    private int[] blockSum;
    private int blockSize;
    public NumArray(int[] nums) {
        this.nums = nums;
        blockSize = (int) Math.ceil(Math.sqrt(nums.length));
        blockSum = new int[blockSize + 1];
        for (int i = 0; i < nums.length; i++) {
            blockSum[i / blockSize] += nums[i];
        }
    }
    public int sumRange(int left, int right) {
        int sum = 0;
        int startBlock = left / blockSize;
        int endBlock = right / blockSize;
        if (startBlock == endBlock) {
            for (int i = left; i <= right; i++) sum += nums[i];
        } else {
            for (int i = left; i < (startBlock + 1) * blockSize; i++) sum += nums[i];
            for (int b = startBlock + 1; b < endBlock; b++) sum += blockSum[b];
            for (int i = endBlock * blockSize; i <= right; i++) sum += nums[i];
        }
        return sum;
    }
}
